// --- credd.FCred.c_credperm.Remove
// Find element using linear scan. If element is in array, remove, otherwise do nothing
void credd::c_credperm_Remove(credd::FCred& parent, credd::FCredperm& row) {
    i64 n = parent.c_credperm_n;
    if (bool_Update(row.cred_c_credperm_in_ary,false)) {
        credd::FCredperm* *elems = parent.c_credperm_elems;
        // search backward, so that most recently added element is found first.
        // if found, shift array.
        for (i64 i = n-1; i>=0; i--) {
            credd::FCredperm* elem = elems[i]; // fetch element
            if (elem == &row) {
                i64 j = i + 1;
                size_t nbytes = sizeof(credd::FCredperm*) * (n - j);
                memmove(elems + i, elems + j, nbytes);
                parent.c_credperm_n = n - 1;
                break;
            }
        }
    }
}

// --- credd.FCred.c_credperm.Reserve
