// --- credd.FDb._db.InsertStrptrMaybe
// Parse strptr into known type and add to database.
// Return value is true unless an error occurs. If return value is false, algo_lib::_db.errtext has error text
bool credd::InsertStrptrMaybe(algo::strptr str) {
    bool retval = true;
    credd::TableId table_id(-1);
    value_SetStrptrMaybe(table_id, algo::GetTypeTag(str));
    switch (value_GetEnum(table_id)) {
        case credd_TableId_creddb_Cred: { // finput:credd.FDb.cred
            creddb::Cred elem;
            retval = creddb::Cred_ReadStrptrMaybe(elem, str);
            retval = retval && cred_InputMaybe(elem);
            break;
        }
        case credd_TableId_creddb_Credperm: { // finput:credd.FDb.credperm
            creddb::Credperm elem;
            retval = creddb::Credperm_ReadStrptrMaybe(elem, str);
            retval = retval && credperm_InputMaybe(elem);
            break;
        }
        case credd_TableId_creddb_Master: { // finput:credd.FDb.master
            creddb::Master elem;
            retval = creddb::Master_ReadStrptrMaybe(elem, str);
            retval = retval && master_InputMaybe(elem);
            break;
        }
        default:
        break;
    } //switch
    if (!retval) {
        algo_lib::NoteInsertErr(str); // increment error counter
    }
    return retval;
}

// --- credd.FDb._db.LoadTuplesMaybe
// Load all finputs from given directory.
bool credd::LoadTuplesMaybe(algo::strptr root, bool recursive) {
    bool retval = true;
    if (FileQ(root)) {
        retval = credd::LoadTuplesFile(root, recursive);
    } else if (root == "-") {
        retval = credd::LoadTuplesFd(algo::Fildes(0),"(stdin)",recursive);
    } else if (DirectoryQ(root)) {
        retval = retval && credd::LoadTuplesFile(algo::SsimFname(root,"dmmeta.dispsigcheck"),recursive);
        retval = retval && credd::LoadTuplesFile(algo::SsimFname(root,"creddb.master"),recursive);
        retval = retval && credd::LoadTuplesFile(algo::SsimFname(root,"creddb.cred"),recursive);
        retval = retval && credd::LoadTuplesFile(algo::SsimFname(root,"creddb.credperm"),recursive);
    } else {
        algo_lib::AppendErrtext("path", root);
        algo_lib::AppendErrtext("comment", "Wrong working directory?");
        retval = false;
    }
    return retval;
}

// --- credd.FDb._db.LoadTuplesFile
// Load all finputs from given file.
// Read tuples from file FNAME into this namespace's in-memory database.
// If RECURSIVE is TRUE, then also load these tuples into any parent namespaces
// It a file referred to by FNAME is missing, no error is reported (it's considered an empty set).
// Function returns TRUE if all records were parsed and inserted without error.
// If the function returns FALSE, use algo_lib::DetachBadTags() for error description
bool credd::LoadTuplesFile(algo::strptr fname, bool recursive) {
    bool retval = true;
    algo_lib::FFildes fildes;
    // missing files are not an error
    fildes.fd = OpenRead(fname,algo::FileFlags());
    if (ValidQ(fildes.fd)) {
        retval = LoadTuplesFd(fildes.fd, fname, recursive);
    }
    return retval;
}

// --- credd.FDb._db.LoadTuplesFd
// Load all finputs from given file descriptor.
bool credd::LoadTuplesFd(algo::Fildes fd, algo::strptr fname, bool recursive) {
    bool retval = true;
    ind_beg(algo::FileLine_curs,line,fd) {
        if (recursive) {
            retval = retval && algo_lib::InsertStrptrMaybe(line);
        }
        retval = retval && credd::InsertStrptrMaybe(line);
        if (!retval) {
            algo_lib::_db.errtext << eol
            << fname << ":"
            << (ind_curs(line).i+1)
            << ": " << line << eol;
            break;
        }
    }ind_end;
    return retval;
}

// --- credd.FDb._db.LoadSsimfileMaybe
// Load specified ssimfile.
bool credd::LoadSsimfileMaybe(algo::strptr fname, bool recursive) {
    bool retval = true;
    if (FileQ(fname)) {
        retval = credd::LoadTuplesFile(fname, recursive);
    }
    return retval;
}

// --- credd.FDb._db.Steps
// Call every step of this process, band by band, each band in dependency order
void credd::Steps() {
    algo_lib::bh_timehook_Call(); // fstep:algo_lib.FDb.bh_timehook  stepband:work
    algo_lib::bh_timehook_idle_Call(); // fstep:algo_lib.FDb.bh_timehook_idle  stepband:idle
    algo_lib::giveup_time_Call(); // fstep:algo_lib.FDb.giveup_time  stepband:yield
}

// --- credd.FDb._db.RemoveStrptrMaybe
// Parse strptr into known type and remove matching record from database.
// Return value is true if the record was found and removed, false otherwise.
bool credd::RemoveStrptrMaybe(algo::strptr str) {
    bool retval = true;
    credd::TableId table_id(-1);
    value_SetStrptrMaybe(table_id, algo::GetTypeTag(str));
    switch (value_GetEnum(table_id)) {
        case credd_TableId_creddb_Cred: { // finput:credd.FDb.cred
            // finput credd.FDb.cred: random delete unsupported
            // (need reftype del:Y plus a Thash on the pkey)
            retval = false;
            break;
        }
        case credd_TableId_creddb_Credperm: { // finput:credd.FDb.credperm
            // finput credd.FDb.credperm: random delete unsupported
            // (need reftype del:Y plus a Thash on the pkey)
            retval = false;
            break;
        }
        case credd_TableId_creddb_Master: { // finput:credd.FDb.master
            // finput credd.FDb.master: random delete unsupported
            // (need reftype del:Y plus a Thash on the pkey)
            retval = false;
            break;
        }
        default:
        retval = false;
        break;
    } //switch
    return retval;
}

