// --- credd.FDb.kind.AllocMaybe
// Allocate memory for new element. If out of memory, return NULL.
credd::FKind* credd::kind_AllocMaybe() {
    credd::FKind *row = (credd::FKind*)kind_AllocMem();
    if (row) {
        new (row) credd::FKind; // call constructor
    }
    return row;
}

// --- credd.FDb.kind.InsertMaybe
// Create new row from struct.
// Return pointer to new element, or NULL if insertion failed (due to out-of-memory, duplicate key, etc)
credd::FKind* credd::kind_InsertMaybe(const creddb::Kind &value) {
    credd::FKind *row = &kind_Alloc(); // if out of memory, process dies. if input error, return NULL.
    kind_CopyIn(*row,const_cast<creddb::Kind&>(value));
    bool ok = kind_XrefMaybe(*row); // this may return false
    if (!ok) {
        kind_RemoveLast(); // delete offending row, any existing xrefs are cleared
        row = NULL; // forget this ever happened
    }
    return row;
}

// --- credd.FDb.kind.AllocMem
// Allocate space for one element. If no memory available, return NULL.
void* credd::kind_AllocMem() {
    u64 new_nelems     = _db.kind_n+1;
    // compute level and index on level
    u64 bsr   = algo::u64_BitScanReverse(new_nelems);
    u64 base  = u64(1)<<bsr;
    u64 index = new_nelems-base;
    void *ret = NULL;
    // if level doesn't exist yet, create it
    credd::FKind*  lev   = NULL;
    if (bsr < 36) {
        lev = _db.kind_lary[bsr];
        if (!lev) {
            lev=(credd::FKind*)algo_lib::malloc_AllocMem(sizeof(credd::FKind) * (u64(1)<<bsr));
            _db.kind_lary[bsr] = lev;
        }
    }
    // allocate element from this level
    if (lev) {
        _db.kind_n = i64(new_nelems);
        ret = lev + index;
    }
    return ret;
}

// --- credd.FDb.kind.RemoveAll
// Remove all elements from Lary
void credd::kind_RemoveAll() {
    for (u64 n = _db.kind_n; n>0; ) {
        n--;
        kind_qFind(u64(n)).~FKind(); // destroy last element
        _db.kind_n = i64(n);
    }
}

// --- credd.FDb.kind.RemoveLast
// Delete last element of array. Do nothing if array is empty.
void credd::kind_RemoveLast() {
    u64 n = _db.kind_n;
    if (n > 0) {
        n -= 1;
        kind_qFind(u64(n)).~FKind();
        _db.kind_n = i64(n);
    }
}

