// --- credd.FDb.ind_kind.Find
// Find row by key. Return NULL if not found.
credd::FKind* credd::ind_kind_Find(const algo::strptr& key) {
    u32 index = algo::Smallstr50_Hash(0, key) & (_db.ind_kind_buckets_n - 1);
    credd::FKind *ret = _db.ind_kind_buckets_elems[index];
    for (; ret && !((*ret).kind == key); ret = ret->ind_kind_next) {
    }
    return ret;
}

// --- credd.FDb.ind_kind.FindX
// Look up row by key and return reference. Throw exception if not found
credd::FKind& credd::ind_kind_FindX(const algo::strptr& key) {
    credd::FKind* ret = ind_kind_Find(key);
    vrfy(ret, tempstr() << "credd.key_error  table:ind_kind  key:'"<<key<<"'  comment:'key not found'");
    return *ret;
}

// --- credd.FDb.ind_kind.GetOrCreate
// Find row by key. If not found, create and x-reference a new row with with this key.
credd::FKind& credd::ind_kind_GetOrCreate(const algo::strptr& key) {
    credd::FKind* ret = ind_kind_Find(key);
    if (!ret) { //  if memory alloc fails, process dies; if insert fails, function returns NULL.
        ret         = &kind_Alloc();
        (*ret).kind = key;
        bool good = kind_XrefMaybe(*ret);
        if (!good) {
            kind_RemoveLast(); // delete offending row, any existing xrefs are cleared
            ret = NULL;
        }
    }
    vrfy(ret, tempstr() << "credd.create_error  table:ind_kind  key:'"<<key<<"'  comment:'bad xref'");
    return *ret;
}

// --- credd.FDb.ind_kind.InsertMaybe
// Insert row into hash table. Return true if row is reachable through the hash after the function completes.
bool credd::ind_kind_InsertMaybe(credd::FKind& row) {
    bool retval = true; // if already in hash, InsertMaybe returns true
    if (LIKELY(row.ind_kind_next == (credd::FKind*)-1)) {// check if in hash already
        row.ind_kind_hashval = algo::Smallstr50_Hash(0, row.kind);
        ind_kind_Reserve(1);
        u32 index = row.ind_kind_hashval & (_db.ind_kind_buckets_n - 1);
        credd::FKind* *prev = &_db.ind_kind_buckets_elems[index];
        do {
            credd::FKind* ret = *prev;
            if (!ret) { // exit condition 1: reached the end of the list
                break;
            }
            if ((*ret).kind == row.kind) { // exit condition 2: found matching key
                retval = false;
                break;
            }
            prev = &ret->ind_kind_next;
        } while (true);
        if (retval) {
            row.ind_kind_next = *prev;
            _db.ind_kind_n++;
            *prev = &row;
        }
    }
    return retval;
}

// --- credd.FDb.ind_kind.Remove
// Remove reference to element from hash index. If element is not in hash, do nothing
void credd::ind_kind_Remove(credd::FKind& row) {
    if (LIKELY(row.ind_kind_next != (credd::FKind*)-1)) {// check if in hash already
        u32 index = row.ind_kind_hashval & (_db.ind_kind_buckets_n - 1);
        credd::FKind* *prev = &_db.ind_kind_buckets_elems[index]; // addr of pointer to current element
        while (credd::FKind *next = *prev) {                          // scan the collision chain for our element
            if (next == &row) {        // found it?
                *prev = next->ind_kind_next; // unlink (singly linked list)
                _db.ind_kind_n--;
                row.ind_kind_next = (credd::FKind*)-1;// not-in-hash
                break;
            }
            prev = &next->ind_kind_next;
        }
    }
}

// --- credd.FDb.ind_kind.Reserve
// Reserve enough room in the hash for N more elements. Return success code.
void credd::ind_kind_Reserve(int n) {
    ind_kind_AbsReserve(_db.ind_kind_n + n);
}

// --- credd.FDb.ind_kind.AbsReserve
// Reserve enough room for exacty N elements. Return success code.
void credd::ind_kind_AbsReserve(int n) {
    u32 old_nbuckets = _db.ind_kind_buckets_n;
    u32 new_nelems   = n;
    // # of elements has to be roughly equal to the number of buckets
    if (new_nelems > old_nbuckets) {
        int new_nbuckets = i32_Max(algo::BumpToPow2(new_nelems), u32(4));
        u32 old_size = old_nbuckets * sizeof(credd::FKind*);
        u32 new_size = new_nbuckets * sizeof(credd::FKind*);
        // allocate new array. we don't use Realloc since copying is not needed and factor of 2 probably
        // means new memory will have to be allocated anyway
        credd::FKind* *new_buckets = (credd::FKind**)algo_lib::malloc_AllocMem(new_size);
        if (UNLIKELY(!new_buckets)) {
            FatalErrorExit("credd.out_of_memory  field:credd.FDb.ind_kind");
        }
        memset(new_buckets, 0, new_size); // clear pointers
        // rehash all entries
        for (int i = 0; i < _db.ind_kind_buckets_n; i++) {
            credd::FKind* elem = _db.ind_kind_buckets_elems[i];
            while (elem) {
                credd::FKind &row        = *elem;
                credd::FKind* next       = row.ind_kind_next;
                u32 index          = row.ind_kind_hashval & (new_nbuckets-1);
                row.ind_kind_next     = new_buckets[index];
                new_buckets[index] = &row;
                elem               = next;
            }
        }
        // free old array
        algo_lib::malloc_FreeMem(_db.ind_kind_buckets_elems, old_size);
        _db.ind_kind_buckets_elems = new_buckets;
        _db.ind_kind_buckets_n = new_nbuckets;
    }
}

// --- credd.FDb.perm.Alloc
// Allocate memory for new default row.
// If out of memory, process is killed.
credd::FPerm& credd::perm_Alloc() {
    credd::FPerm* row = perm_AllocMaybe();
    if (UNLIKELY(row == NULL)) {
        FatalErrorExit("credd.out_of_mem  field:credd.FDb.perm  comment:'Alloc failed'");
    }
    return *row;
}

// --- credd.FDb.perm.AllocMaybe
// Allocate memory for new element. If out of memory, return NULL.
credd::FPerm* credd::perm_AllocMaybe() {
    credd::FPerm *row = (credd::FPerm*)perm_AllocMem();
    if (row) {
        new (row) credd::FPerm; // call constructor
    }
    return row;
}

// --- credd.FDb.perm.InsertMaybe
// Create new row from struct.
// Return pointer to new element, or NULL if insertion failed (due to out-of-memory, duplicate key, etc)
credd::FPerm* credd::perm_InsertMaybe(const creddb::Perm &value) {
    credd::FPerm *row = &perm_Alloc(); // if out of memory, process dies. if input error, return NULL.
    perm_CopyIn(*row,const_cast<creddb::Perm&>(value));
    bool ok = perm_XrefMaybe(*row); // this may return false
    if (!ok) {
        perm_RemoveLast(); // delete offending row, any existing xrefs are cleared
        row = NULL; // forget this ever happened
    }
    return row;
}

// --- credd.FDb.perm.AllocMem
// Allocate space for one element. If no memory available, return NULL.
void* credd::perm_AllocMem() {
    u64 new_nelems     = _db.perm_n+1;
    // compute level and index on level
    u64 bsr   = algo::u64_BitScanReverse(new_nelems);
    u64 base  = u64(1)<<bsr;
    u64 index = new_nelems-base;
    void *ret = NULL;
    // if level doesn't exist yet, create it
    credd::FPerm*  lev   = NULL;
    if (bsr < 36) {
        lev = _db.perm_lary[bsr];
        if (!lev) {
            lev=(credd::FPerm*)algo_lib::malloc_AllocMem(sizeof(credd::FPerm) * (u64(1)<<bsr));
            _db.perm_lary[bsr] = lev;
        }
    }
    // allocate element from this level
    if (lev) {
        _db.perm_n = i64(new_nelems);
        ret = lev + index;
    }
    return ret;
}

// --- credd.FDb.perm.RemoveAll
// Remove all elements from Lary
void credd::perm_RemoveAll() {
    for (u64 n = _db.perm_n; n>0; ) {
        n--;
        perm_qFind(u64(n)).~FPerm(); // destroy last element
        _db.perm_n = i64(n);
    }
}

// --- credd.FDb.perm.RemoveLast
// Delete last element of array. Do nothing if array is empty.
void credd::perm_RemoveLast() {
    u64 n = _db.perm_n;
    if (n > 0) {
        n -= 1;
        perm_qFind(u64(n)).~FPerm();
        _db.perm_n = i64(n);
    }
}

