// --- credd.FDb.perm.XrefMaybe
// Insert row into all appropriate indices. If error occurs, store error
// in algo_lib::_db.errtext and return false. Caller must Delete or Unref such row.
bool credd::perm_XrefMaybe(credd::FPerm &row) {
    bool retval = true;
    (void)row;
    credd::FKind* p_kind = credd::ind_kind_Find(kind_Get(row));
    if (UNLIKELY(!p_kind)) {
        algo_lib::ResetErrtext() << "credd.bad_xref  index:credd.FDb.ind_kind" << Keyval("key", kind_Get(row));
        return false;
    }
    // perm: save pointer to kind
    if (true) { // user-defined insert condition
        row.p_kind = p_kind;
    }
    // insert perm into index c_perm
    if (true) { // user-defined insert condition
        c_perm_Insert(*p_kind, row);
    }
    // insert perm into index ind_perm
    if (true) { // user-defined insert condition
        bool success = ind_perm_InsertMaybe(row);
        if (UNLIKELY(!success)) {
            ch_RemoveAll(algo_lib::_db.errtext);
            algo_lib::_db.errtext << "credd.duplicate_key  xref:credd.FDb.ind_perm"; // check for duplicate key
            return false;
        }
    }
    return retval;
}

