    if (!ret) { //  if memory alloc fails, process dies; if insert fails, function returns NULL.
        ret         = &cred_Alloc();
        (*ret).cred = key;
        bool good = cred_XrefMaybe(*ret);
        if (!good) {
            cred_RemoveLast(); // delete offending row, any existing xrefs are cleared
            ret = NULL;
        }
    }
