// --- credd.FDb.ind_cred.InsertMaybe
// Insert row into hash table. Return true if row is reachable through the hash after the function completes.
bool credd::ind_cred_InsertMaybe(credd::FCred& row) {
    bool retval = true; // if already in hash, InsertMaybe returns true
    if (LIKELY(row.ind_cred_next == (credd::FCred*)-1)) {// check if in hash already
        row.ind_cred_hashval = algo::Smallstr50_Hash(0, row.cred);
        ind_cred_Reserve(1);
        u32 index = row.ind_cred_hashval & (_db.ind_cred_buckets_n - 1);
        credd::FCred* *prev = &_db.ind_cred_buckets_elems[index];
        do {
            credd::FCred* ret = *prev;
            if (!ret) { // exit condition 1: reached the end of the list
                break;
            }
            if ((*ret).cred == row.cred) { // exit condition 2: found matching key
                retval = false;
                break;
            }
            prev = &ret->ind_cred_next;
        } while (true);
        if (retval) {
            row.ind_cred_next = *prev;
            _db.ind_cred_n++;
            *prev = &row;
        }
    }
    return retval;
}

// --- credd.FDb.ind_cred.Remove
// Remove reference to element from hash index. If element is not in hash, do nothing
void credd::ind_cred_Remove(credd::FCred& row) {
    if (LIKELY(row.ind_cred_next != (credd::FCred*)-1)) {// check if in hash already
        u32 index = row.ind_cred_hashval & (_db.ind_cred_buckets_n - 1);
        credd::FCred* *prev = &_db.ind_cred_buckets_elems[index]; // addr of pointer to current element
        while (credd::FCred *next = *prev) {                          // scan the collision chain for our element
            if (next == &row) {        // found it?
                *prev = next->ind_cred_next; // unlink (singly linked list)
                _db.ind_cred_n--;
                row.ind_cred_next = (credd::FCred*)-1;// not-in-hash
                break;
            }
            prev = &next->ind_cred_next;
        }
    }
}

// --- credd.FDb.ind_cred.Reserve
// Reserve enough room in the hash for N more elements. Return success code.
void credd::ind_cred_Reserve(int n) {
    ind_cred_AbsReserve(_db.ind_cred_n + n);
}

// --- credd.FDb.ind_cred.AbsReserve
// Reserve enough room for exacty N elements. Return success code.
void credd::ind_cred_AbsReserve(int n) {
    u32 old_nbuckets = _db.ind_cred_buckets_n;
    u32 new_nelems   = n;
    // # of elements has to be roughly equal to the number of buckets
    if (new_nelems > old_nbuckets) {
        int new_nbuckets = i32_Max(algo::BumpToPow2(new_nelems), u32(4));
        u32 old_size = old_nbuckets * sizeof(credd::FCred*);
        u32 new_size = new_nbuckets * sizeof(credd::FCred*);
        // allocate new array. we don't use Realloc since copying is not needed and factor of 2 probably
        // means new memory will have to be allocated anyway
        credd::FCred* *new_buckets = (credd::FCred**)algo_lib::malloc_AllocMem(new_size);
        if (UNLIKELY(!new_buckets)) {
            FatalErrorExit("credd.out_of_memory  field:credd.FDb.ind_cred");
        }
        memset(new_buckets, 0, new_size); // clear pointers
        // rehash all entries
        for (int i = 0; i < _db.ind_cred_buckets_n; i++) {
            credd::FCred* elem = _db.ind_cred_buckets_elems[i];
            while (elem) {
                credd::FCred &row        = *elem;
                credd::FCred* next       = row.ind_cred_next;
                u32 index          = row.ind_cred_hashval & (new_nbuckets-1);
                row.ind_cred_next     = new_buckets[index];
                new_buckets[index] = &row;
                elem               = next;
            }
        }
        // free old array
        algo_lib::malloc_FreeMem(_db.ind_cred_buckets_elems, old_size);
        _db.ind_cred_buckets_elems = new_buckets;
        _db.ind_cred_buckets_n = new_nbuckets;
    }
}

