// --- credd.FKind.c_perm.Insert
// Insert pointer to row into array. Row must not already be in array;
// no duplicate check is performed, so a duplicate insert silently appears twice.
void credd::c_perm_Insert(credd::FKind& parent, credd::FPerm& row) {
    if (!row.kind_c_perm_in_ary) {
        c_perm_Reserve(parent, 1);
        u64 n  = parent.c_perm_n++;
        parent.c_perm_elems[n] = &row;
        row.kind_c_perm_in_ary = true;
    }
}

// --- credd.FKind.c_perm.InsertMaybe
// Insert pointer to row in array.
// If row is already in the array, do nothing.
// Return value: whether element was inserted into array.
bool credd::c_perm_InsertMaybe(credd::FKind& parent, credd::FPerm& row) {
    bool retval = !kind_c_perm_InAryQ(row);
    c_perm_Insert(parent,row); // check is performed in _Insert again
    return retval;
}

// --- credd.FKind.c_perm.Remove
// Find element using linear scan. If element is in array, remove, otherwise do nothing
void credd::c_perm_Remove(credd::FKind& parent, credd::FPerm& row) {
    i64 n = parent.c_perm_n;
    if (bool_Update(row.kind_c_perm_in_ary,false)) {
        credd::FPerm* *elems = parent.c_perm_elems;
        // search backward, so that most recently added element is found first.
        // if found, shift array.
        for (i64 i = n-1; i>=0; i--) {
            credd::FPerm* elem = elems[i]; // fetch element
            if (elem == &row) {
                i64 j = i + 1;
                size_t nbytes = sizeof(credd::FPerm*) * (n - j);
                memmove(elems + i, elems + j, nbytes);
                parent.c_perm_n = n - 1;
                break;
            }
        }
    }
}

// --- credd.FKind.c_perm.Reserve
// Reserve space in index for N more elements;
void credd::c_perm_Reserve(credd::FKind& parent, u64 n) {
    u64 old_max = parent.c_perm_max;
    if (UNLIKELY(parent.c_perm_n + n > old_max)) {
        u64 new_max  = u64_Max(u64_Max(old_max * 2, parent.c_perm_n + n), 4);
        u64 old_size = old_max * sizeof(credd::FPerm*);
        u64 new_size = new_max * sizeof(credd::FPerm*);
        void *new_mem = algo_lib::malloc_ReallocMem(parent.c_perm_elems, old_size, new_size);
        if (UNLIKELY(!new_mem)) {
            FatalErrorExit("credd.out_of_memory  field:credd.FKind.c_perm");
        }
        parent.c_perm_elems = (credd::FPerm**)new_mem;
        parent.c_perm_max = new_max;
    }
}

// --- credd.FKind..Uninit
void credd::FKind_Uninit(credd::FKind& parent) {
    ind_kind_Remove(parent); // remove kind from index ind_kind

    // credd.FKind.c_perm.Uninit (Ptrary)  //Permissions this provider offers
    algo_lib::malloc_FreeMem(parent.c_perm_elems, sizeof(credd::FPerm*)*parent.c_perm_max); // (credd.FKind.c_perm)
}

