// --- credd.TableId.value.ToCstr
// Convert numeric value of field to one of predefined string constants.
// If string is found, return a static C string. Otherwise, return NULL.
const char* credd::value_ToCstr(const credd::TableId& parent) {
    const char *ret = NULL;
    switch(value_GetEnum(parent)) {
        case credd_TableId_creddb_Cred     : ret = "creddb.Cred";  break;
        case credd_TableId_creddb_Credperm : ret = "creddb.Credperm";  break;
        case credd_TableId_creddb_Master   : ret = "creddb.Master";  break;
    }
    return ret;
}

// --- credd.TableId.value.Print
// Convert value to a string. First, attempt conversion to a known string.
// If no string matches, print value as a numeric value.
void credd::value_Print(const credd::TableId& parent, algo::cstring &lhs) {
    const char *strval = value_ToCstr(parent);
    if (strval) {
        lhs << strval;
    } else {
        lhs << parent.value;
    }
}

